#!/usr/bin/env python3
"""Print a greeting. Optional --name customizes who is greeted."""
import argparse


def main() -> None:
    parser = argparse.ArgumentParser(description="Print a greeting.")
    parser.add_argument(
        "-n", "--name",
        default=None,
        help="Name to greet (default: print 'Hello from Python!')",
    )
    args = parser.parse_args()

    if args.name is None:
        print("Hello from Python!")
    else:
        print(f"Hello, {args.name}!")


if __name__ == "__main__":
    main()
